#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S. Import LbB_NLoops.NDig.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Definition DPL_RET_SNP : Z := 0x132604.

Section DoPut.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Variable gd : Z.
  Hypothesis Hgd : 0 <= gd < 2 ^ 64.
  Variables (R : bvmap 5 word) (M : mem) (ssp ds v fl ret lo shi : Z) (fillw : word).
  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 ssp.
  Hypothesis Htp : getr R 4%bv = Z_to_bv 64 ATP.
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (ds + 8).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 (ds + 112).
  Hypothesis Ha3 : getr R 13%bv = fillw.
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis Hslo : 2 ^ 33 <= ssp - 8192.
  Hypothesis Hshi : ssp < 2 ^ 47.
  Hypothesis Hal : ssp mod 16 = 0.
  Hypothesis HD : mdef M (ssp - 8192) 8192.
  Hypothesis Hds : 0x6e8000 <= ds /\ ds + 392 <= 2 ^ 47 /\ ds mod 8 = 0.
  Hypothesis DJds : ds + 392 <= ssp - 8192 \/ ssp <= ds.
  Hypothesis Gfl : fld SEGS M (ds + 120) 4 fl.
  Hypothesis Hfl : fl = LbB_DiagStmt.DS_FL0 \/ fl = LbB_DiagStmt.DS_FLHEX.
  Hypothesis Gloc : fld SEGS M (ds + 160) 8 LbB_DRep.LOC_IMP_A.
  Hypothesis Gwidth : fld SEGS M (ds + 136) 8 0.
  Hypothesis Gvsb : fld SEGS M (ds + 8) 8 LbB_DRep.VT_SB_A.
  Hypothesis Hvp : v < 2 ^ 63.
  Hypothesis DT : dstat_rs D_DIAG_A M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 gd.

  Hypothesis RF : rfull R.
  Hypothesis NI : ninv lo shi M.
  Hypothesis STK : stk asegs M lo ssp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LOS : lo + 8192 <= ssp.
  Hypothesis SHI : ssp + 4 <= shi.

  Let ROC : mem_inv asegs M := proj1 NI.
  Let RRC : relro_clear M := proj2 (proj2 (proj2 NI)).
  Let AF1 : 0x7fff7f800000 <= aceil := proj1 (proj1 aceil_facts).
  Let FTD : fld SEGS M ATDLOC 8 AGLOBAL_LOCALE := tdl_fld_of_dstat M DT.

  #[local] Notation dpm := (dpm R M ssp ds ret fillw 0x1326dc lo shi).
  #[local] Notation dps := (dps R M ssp ds ret fillw lo shi).

  Lemma doput_back : forall nc R2 M2, dps nc R2 M2 ->
